  "-2,-5": {"poi":{"name":"Watch Bunkhouse","type":"barracks","access":"restricted","description":"A long stone bunkhouse with its back built straight into the wall. Two rows of three-deep cots, lockers stamped with watch-numbers, and a stove always banked. Off-shift watchmen pull boots up here between gate-watch and wall-watch; the sergeants drink at the table by the door where they can see everyone come and go."},"doors":[{"x":-2,"y":-4},{"x":-3,"y":-4}],"terrain":"indoor","wallside":true},
