  "-2,-4": {"poi":{"name":"Crown Guardpost","type":"barracks","access":"restricted","description":"A squat barracks-block built into the wall beside the gate. Bunks stacked three high under low rafters; pike-racks polished by passing shoulders; a kettle always near boil over a peat-fire that the sergeants refuse to let go out. The gate-watch sleeps here in shifts, and the city's first answer to a gate-side problem is whoever happens to be lacing boots."},"doors":[{"x":-2,"y":-3}],"terrain":"indoor"},
