  "3,0": {"poi":{"name":"Lower Petition Steps","type":"hall","access":"public","description":"A broad paved approach crowded from sunrise: widows with petitions, debtors with sponsors, merchants with sealed cases, foreigners with interpreters, and soldiers escorting people who learned too late that law moves faster than mercy. The advocate-cloister stands above; debt-collectors wait below."},"doors":[{"x":4,"y":0},{"x":3,"y":-1},{"x":2,"y":0},{"x":2,"y":1},{"x":3,"y":1},{"x":4,"y":-1}],"terrain":"street"},
