  "-3,1": {"poi":{"name":"Proclamation Board","type":"site","access":"public","description":"A waist-high oak board nailed to the gable of the corner-house, hooded by a shingle to keep the rain off. Layers of parchment overlap layers — toll-rates struck through and re-posted, lost-bond notices, a list of names the watch wants brought in, a militia muster for the third bell. Beside it a bench worn shiny by sitters; a one-eyed reader takes a half-coin to read out anything that matters."},"doors":[{"x":-2,"y":1},{"x":-2,"y":0},{"x":-3,"y":0},{"x":-3,"y":2},{"x":-4,"y":1},{"x":-4,"y":2}],"terrain":"street"},
